1	package agentusageview
2	
3	import (
4		"errors"
5		"log"
6		"os"
7	
8		"github.com/charmbracelet/bubbles/spinner"
9		tea "github.com/charmbracelet/bubbletea"
10	
11		"github.com/anthnel/devdesk/internal/agentusage"
12		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	)
15	
16	// Update handles messages.
17	func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
18		switch msg := msg.(type) {
19		case tea.WindowSizeMsg:
20			return m.handleResize(msg)
21		case sessionListLoadedMsg:
22			return m.handleListLoaded(msg)
23		case usageDeltaMsg:
24			return m.handleUsageDelta(msg)
25		case usagePollTickMsg:
26			return m.handlePollTick(msg)
27		case agentsResumeMsg:
28			return m.handleResume()
29		case spinner.TickMsg:
30			return m.handleSpinnerTick(msg)
31		case tea.KeyMsg:
32			return m.handleKey(msg)
33		}
34		m.footer.Handle(msg)
35		return m, nil
36	}
37	
38	// handleResize sizes both tables, so going back from the agents level finds the
39	// sessions table already fitted. The full viewport width, borders included
40	// (Rule 116).
41	func (m Model) handleResize(msg tea.WindowSizeMsg) (tea.Model, tea.Cmd) {
42		m.width, m.height = msg.Width, max(msg.Height-1, 1)
43		m.table.Resize(m.width, m.height)
44		m.agentTable.Resize(m.width, m.height)
45		return m, nil
46	}
47	
48	// handleListLoaded takes a listing, or ignores one from a superseded read.
49	// A failed read keeps the rows already shown: they are dated, not wrong.
50	func (m Model) handleListLoaded(msg sessionListLoadedMsg) (tea.Model, tea.Cmd) {
51		if msg.gen != m.gen {
52			return m, nil
53		}
54		m.loading = false
55		if msg.err != nil {
56			// The error can name a path; it is logged, never shown (Rule 128).
57			log.Printf("ERROR [agentusageview] list sessions: %v", msg.err)
58			m.loadErr = true
59			return m, nil
60		}
61		m.loadErr = false
62		m.root = msg.root
63		m.omitted = msg.listing.Omitted
64		m.table.SetItems(rowsOf(msg))
65		return m, nil
66	}
67	
68	// rowsOf folds each project once, so no Cell does it per frame.
69	func rowsOf(msg sessionListLoadedMsg) []sessionRow {
70		rows := make([]sessionRow, len(msg.listing.Sessions))
71		for i, s := range msg.listing.Sessions {
72			project := noProject
73			if s.Project != "" {
74				project = theme.FoldHome(s.Project)
75			}
76			rows[i] = sessionRow{Session: s, project: project}
77		}
78		return rows
79	}
80	
81	// handleSpinnerTick advances the spinner only while a read or a parse is in
82	// flight, so the chain ends with the load.
83	func (m Model) handleSpinnerTick(msg spinner.TickMsg) (tea.Model, tea.Cmd) {
84		if !m.loading && !m.agentsLoading {
85			return m, nil
86		}
87		var cmd tea.Cmd
88		m.spinner, cmd = m.spinner.Update(msg)
89		m.footer.SetSpinnerFrame(m.spinner.View())
90		return m, cmd
91	}
92	
93	// handleUsageDelta takes the answer to the read in flight, or drops one that
94	// is for another generation or that nobody is waiting for. A failed read keeps
95	// the rows already shown.
96	func (m Model) handleUsageDelta(msg usageDeltaMsg) (tea.Model, tea.Cmd) {
97		if msg.gen != m.agentGen || m.level != levelAgents || !m.reading || m.agg == nil {
98			return m, nil
99		}
100		m.reading = false
101		if msg.err != nil {
102			return m.failRead(msg.err)
103		}
104		if err := m.agg.Apply(msg.delta); err != nil {
105			// Not read from the current cursor: read again from where it is now.
106			log.Printf("ERROR [agentusageview] apply delta: %v", err)
107			m.reading = true
108			return m, readDeltaCmd(m.agentGen, m.agg.Cursor())
109		}
110		m.agentsErr = false
111		if msg.delta.Full() || !msg.delta.Empty() {
112			m = m.withUsage(m.agg.Usage(), msg.delta.Full())
113		}
114		if m.fullPending {
115			m.fullPending = false
116			return m, m.startRead(true)
117		}
118		m.agentsLoading = false
119		if m.agg.Activity().Settled(msg.at, quietPeriod) {
120			m.pollStopped = true
121			return m, nil // nothing left to wait for: the chain ends here
122		}
123		return m, pollTickCmd(m.agentGen)
124	}
125	
126	// failRead records a failed read. Only the first failure of a streak is
127	// logged. The error names files by base name only; it never reaches the UI.
128	// A deleted transcript ends the poll chain; any other failure retries, after
129	// the full read a ctrl+r left pending, if there is one.
130	func (m Model) failRead(err error) (tea.Model, tea.Cmd) {
131		if !m.agentsErr {
132			log.Printf("ERROR [agentusageview] read session: %v", err)
133		}
134		m.agentsErr = true
135		if errors.Is(err, os.ErrNotExist) {
136			m.agentsLoading, m.fullPending, m.pollStopped = false, false, true
137			return m, nil
138		}
139		if m.fullPending {
140			m.fullPending = false
141			return m, m.startRead(true)
142		}
143		m.agentsLoading = false
144		return m, pollTickCmd(m.agentGen)
145	}
146	
147	// handlePollTick starts the incremental read a tick asks for, unless the tick
148	// belongs to a superseded chain or a read is already in flight. No spinner:
149	// polling is silent.
150	func (m Model) handlePollTick(msg usagePollTickMsg) (tea.Model, tea.Cmd) {
151		if msg.gen != m.agentGen || m.level != levelAgents || m.agg == nil || m.reading || m.pollStopped {
152			return m, nil
153		}
154		return m, m.startRead(false)
155	}
156	
157	// Leave stops the open session's chain when the router switches away: the new
158	// generation drops any tick or read still in flight, and nothing is awaited
159	// any more. The session stays open and coming back resumes it (handleResume).
160	// A pending ctrl+r is kept, and so is a full read lost in flight (a ctrl+r, or
161	// the open's first read): the resume repeats it as a full read. It never refuses.
162	func (m Model) Leave() (tea.Model, tea.Cmd, bool) {
163		if m.level == levelAgents {
164			m.agentGen++
165			m.fullPending = m.fullPending || (m.reading && m.agentsLoading)
166			m.reading, m.agentsLoading = false, false
167		}
168		return m, nil, true
169	}
170	
171	// handleResume restarts the open session's chain under a new generation, which
172	// drops the answers of any earlier chain. It reads from the cursor, silently;
173	// a ctrl+r left pending by Leave becomes a full read, with its spinner.
174	func (m Model) handleResume() (tea.Model, tea.Cmd) {
175		if m.level != levelAgents || m.agg == nil {
176			return m, nil
177		}
178		m.agentGen++
179		m.pollStopped = false
180		if m.fullPending {
181			m.fullPending = false
182			return m, tea.Batch(m.startRead(true), m.spinner.Tick)
183		}
184		return m, m.startRead(false)
185	}
186	
187	// startRead marks a read in flight and returns it; full reads everything again.
188	func (m *Model) startRead(full bool) tea.Cmd {
189		c := m.agg.Cursor()
190		if full {
191			c = c.Rewound()
192			m.agentsLoading, m.fullPending, m.pollStopped = true, false, false
193		}
194		m.reading = true
195		return readDeltaCmd(m.agentGen, c)
196	}
197	
198	// handleKey gives the filter the keyboard first; ctrl+r refreshes the level on
199	// screen, → and enter open a session, ← and esc go back.
200	func (m Model) handleKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
201		if m.InEditMode() {
202			return m, m.activeTable(msg)
203		}
204		key := msg.String()
205		if key == "ctrl+r" {
206			return m.refresh()
207		}
208		a := m.availability()
209		switch key {
210		case "right", "enter":
211			return m.guard(a.Open, m.openSelected)
212		case "left", "esc":
213			// Silent at the top level: a stray esc is not worth a footer line.
214			if a.Close.Enabled() {
215				return m.closeAgents()
216			}
217		case ".":
218			if m.level == levelAgents {
219				return m.cycleAgentSort(msg)
220			}
221		}
222		return m, m.activeTable(msg)
223	}
224	
225	// agentsTree reports whether the agents table shows the tree: no sort active.
226	func (m Model) agentsTree() bool {
227		column, _ := m.agentTable.SortState()
228		return column < 0
229	}
230	
231	// cycleAgentSort hands `.` to the agents table, then rebuilds the rows so the
232	// branches follow the new order: a sorted list is flat, a branch there would
233	// lie about who is whose child.
234	func (m Model) cycleAgentSort(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
235		selected, hadSelection := m.selectedAgentKey()
236		cmd := m.agentTable.Update(msg)
237		m.agentTable.SetItems(agentRows(m.usage, m.agentsTree()))
238		m.agentTable.Remeasure() // the Agent column narrows or widens by the branch
239		if hadSelection {
240			m.selectAgentKey(selected)
241		}
242		return m, cmd
243	}
244	
245	// activeTable hands a key to the table of the level on screen.
246	func (m *Model) activeTable(msg tea.KeyMsg) tea.Cmd {
247		if m.level == levelAgents {
248			return m.agentTable.Update(msg)
249		}
250		return m.table.Update(msg)
251	}
252	
253	// openSelected opens the selected session's agents. The table stays empty,
254	// headers included, until the parse answers (Rule 139).
255	func (m Model) openSelected() (tea.Model, tea.Cmd) {
256		row, _ := m.table.Selected() // availability checked a row exists
257		m.usage = agentusage.Usage{}
258		m.level = levelAgents
259		m.open = row.Session
260		m.agentGen++
261		m.agg = agentusage.NewAggregate(row.Parent)
262		m.fullPending, m.agentsErr = false, false
263		m.agentTable.FilterBar().ClearSearch() // a filter typed for another session
264		m.agentTable.SetItems(nil)
265		return m, tea.Batch(m.startRead(true), m.spinner.Tick)
266	}
267	
268	// closeAgents returns to the sessions, cursor and filter as they were. Bumping
269	// agentGen drops a parse still in flight.
270	func (m Model) closeAgents() (tea.Model, tea.Cmd) {
271		m.level = levelSessions
272		m.agentGen++
273		m.agentsLoading, m.agentsErr = false, false
274		m.agg, m.reading, m.fullPending = nil, false, false
275		m.usage = agentusage.Usage{}
276		m.agentTable.SetItems(nil)
277		return m, nil
278	}
279	
280	// refresh starts a new read of the level on screen under a new generation.
281	// The rows stay on screen.
282	func (m Model) refresh() (tea.Model, tea.Cmd) {
283		if m.level == levelAgents {
284			return m.refreshAgents()
285		}
286		m.gen++
287		m.loading = true
288		m.loadErr = false
289		return m, tea.Batch(listSessionsCmd(m.gen), m.spinner.Tick)
290	}
291	
292	// refreshAgents reads the open session from the start. A read already in
293	// flight is never doubled (one per Aggregate): the full read follows its answer.
294	func (m Model) refreshAgents() (tea.Model, tea.Cmd) {
295		if m.agg == nil {
296			m.agg = agentusage.NewAggregate(m.open.Parent)
297		}
298		if m.reading {
299			spin := !m.agentsLoading // a spinner chain already runs otherwise
300			m.fullPending, m.agentsLoading = true, true
301			if spin {
302				return m, m.spinner.Tick
303			}
304			return m, nil
305		}
306		m.agentGen++
307		return m, tea.Batch(m.startRead(true), m.spinner.Tick)
308	}
309	
310	// InEditMode tells the router the filter has the keyboard.
311	func (m Model) InEditMode() bool { return m.activeFilterBar().InEditMode() }
312	
313	// FilterBarVisible closes the viewport rectangle around the bar.
314	func (m Model) FilterBarVisible() bool { return m.activeFilterBar().IsVisible() }
315	
316	// activeFilterBar is the bar of the level on screen; each level has its own.
317	func (m Model) activeFilterBar() *sharedcomponents.FilterBar {
318		if m.level == levelAgents {
319			return m.agentTable.FilterBar()
320		}
321		return m.table.FilterBar()
322	}
323

