package agentusageview

import (
	"path/filepath"
	"strconv"

	"github.com/charmbracelet/lipgloss"

	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// baseFooterHeight is the blank line and the message line (Rule 124).
const baseFooterHeight = 2

// View is the table, whatever it holds (Rule 139).
func (m Model) View() string {
	if m.level == levelAgents {
		return m.agentTable.View()
	}
	return m.table.View()
}

// GetTitle names the view, and the project of the open session at the agents
// level (its short ID when the transcript named no project).
func (m Model) GetTitle() string {
	title := theme.IconAgentUsage + " Agent usage"
	if m.level != levelAgents {
		return title
	}
	leaf := shortID(m.open.ID)
	if m.open.Project != "" {
		leaf = filepath.Base(m.open.Project)
	}
	return title + " › " + leaf
}

// shortID is the start of a session ID, as the Session column shows it.
func shortID(id string) string {
	r := []rune(id)
	return string(r[:min(sessionIDPrefix, len(r))])
}

// GetIcon returns nothing: the title carries the icon.
func (m Model) GetIcon() string { return "" }

// GetHeaderInfo counts the sessions on screen, and the ones not listed when
// there are some.
func (m Model) GetHeaderInfo(_ string) []shortcut.HeaderInfo {
	if m.level == levelAgents {
		return m.agentsHeaderInfo()
	}
	info := []shortcut.HeaderInfo{
		{Key: "Sessions", Value: strconv.Itoa(len(m.table.Visible())), Style: theme.HeaderValueStyle},
	}
	if m.omitted > 0 {
		info = append(info, shortcut.HeaderInfo{Key: "Skipped", Value: strconv.Itoa(m.omitted), Style: theme.HeaderValueStyle})
	}
	return info
}

// agentsHeaderInfo counts the agents on screen and their tokens, both following
// the filter.
func (m Model) agentsHeaderInfo() []shortcut.HeaderInfo {
	rows := m.agentTable.Visible()
	var total int64
	for _, r := range rows {
		total += r.Tokens.Total()
	}
	return []shortcut.HeaderInfo{
		{Key: "Agents", Value: strconv.Itoa(len(rows)), Style: theme.HeaderValueStyle},
		{Key: "Tokens", Value: formatTokens(total), Style: theme.HeaderValueStyle},
		{Key: "Updates", Value: m.updatesState(), Style: theme.HeaderValueStyle},
	}
}

// updatesState says whether the open session is polled: live while the chain
// runs, paused once it stopped (settled session, deleted transcript).
func (m Model) updatesState() string {
	if m.level == levelAgents && m.agg != nil && !m.pollStopped {
		return "live"
	}
	return "paused"
}

// GetShortcuts returns the same keys at both levels and in every state; what
// varies is Disabled, from the one availability the handlers also read
// (Rule 130).
func (m Model) GetShortcuts() shortcut.Shortcuts {
	a := m.availability()
	return shortcut.Shortcuts{
		{Key: "ctrl+r", Description: "Refresh"},
		{Key: "→", Description: "Open agents", Disabled: !a.Open.Enabled()},
		{Key: "esc", Description: "Go back", Disabled: !a.Close.Enabled()},
		{Key: "/", Description: "Filter"},
		{Key: ".", Description: "Sort"},
		{Key: "?", Description: "Help"},
	}
}

// GetFooterHeight budgets the footer (Rules 124, 136).
func (m Model) GetFooterHeight() int {
	h := baseFooterHeight + m.activeFilterBar().ExtraHeight()
	if m.level == levelAgents {
		h++ // the breadcrumb row
	}
	return h
}

// RenderFooter renders the breadcrumb at the agents level, the filter bar when
// visible, a blank line, and the message line.
func (m Model) RenderFooter(width int) string {
	line := theme.EmptyLineBg(width) + "\n" + m.footer.View(width, m.status())
	if bar := m.activeFilterBar(); bar.IsVisible() {
		line = bar.View() + "\n" + line
	}
	if m.level == levelAgents {
		line = m.breadcrumb(width) + "\n" + line
	}
	return line
}

// breadcrumb is Sessions › project › ID, the last one active and its parents
// dim, with the one cell of left padding Rule 123 asks for.
func (m Model) breadcrumb(width int) string {
	project := noProject
	if m.open.Project != "" {
		project = theme.ShortPath(m.open.Project, max(width/2, 1))
	}
	base := lipgloss.NewStyle().Background(theme.ColorBackground)
	parents := base.Foreground(theme.ColorDim).Render("Sessions › " + project + " › ")
	active := base.Foreground(theme.ColorSecondary).Bold(true).Render(shortID(m.open.ID))
	return theme.PadWithBg(theme.Bg(" ")+parents+active, width)
}

// status is derived on every frame, with no timer (Rule 128).
//
// The empty sentence needs the listing to be empty in total, not after the
// filter: a filter with no match is not a machine with no sessions.
func (m Model) status() sharedcomponents.Status {
	if m.level == levelAgents {
		return m.agentsStatus()
	}
	switch {
	case m.loadErr:
		return sharedcomponents.Status{
			Text:  "Failed to list Claude Code sessions — check logs",
			Level: sharedcomponents.LevelError,
		}
	case m.loading:
		return sharedcomponents.Status{Text: "Reading Claude Code sessions...", Spinner: true}
	case len(m.table.Items()) == 0:
		return sharedcomponents.Status{Text: "No Claude Code sessions found in " + theme.FoldHome(m.root)}
	}
	return sharedcomponents.Status{}
}

// agentsStatus is the footer state of the agents level.
func (m Model) agentsStatus() sharedcomponents.Status {
	switch {
	case m.agentsErr:
		return sharedcomponents.Status{
			Text:  "Failed to read this session — check logs",
			Level: sharedcomponents.LevelError,
		}
	case m.agentsLoading:
		return sharedcomponents.Status{Text: "Reading session...", Spinner: true}
	case m.usage.Diagnostics.Degraded():
		return sharedcomponents.Status{
			Text:  "Totals are approximate — some transcript data could not be read",
			Level: sharedcomponents.LevelWarning,
		}
	}
	return sharedcomponents.Status{}
}

package agentusageview

import "github.com/anthnel/devdesk/internal/ui/help"

// GetHelpContent returns the help for `?` (Rule 114).
func (m Model) GetHelpContent() help.Content {
	return help.Content{
		Title: "Agent usage",
		Description: "The Claude Code sessions found on this machine, newest first. " +
			"Only where and when a session ran is read — nothing a session says.",
		KeyBindings: []help.KeyBinding{
			{Key: "ctrl+r", Description: "Re-read the whole session from the start (at the sessions level: read the sessions again)"},
			{Key: "→/enter", Description: "Open the selected session's agents"},
			{Key: "←/esc", Description: "Back to the sessions"},
			{Key: "/", Description: "Filter by project or session ID"},
			{Key: ".", Description: "Cycle the sort column (agents: tree, Total largest first, Total smallest first)"},
			{Key: "ctrl+p", Description: "Open command mode"},
			{Key: "?", Description: "Show this help"},
		},
		Sections: []help.Section{
			{
				Title: "Columns",
				Body: "Project: the working directory the session ran in, with your home folded to ~. " +
					"A long path is cut from the left so the project's own name stays visible; a dash means the transcript named none.\n" +
					"Last active: when the session's transcript was last written, in local time.\n" +
					"Session: the start of the session ID. The filter matches the full ID.",
			},
			{
				Title: "Where sessions come from",
				Body: "Claude Code keeps one transcript per session under projects/ in its configuration directory: " +
					"$CLAUDE_CONFIG_DIR when set, otherwise ~/.claude. " +
					"Claude Code deletes old transcripts itself (after 30 days by default), so older sessions disappear from here too.\n" +
					"Sessions that could not be listed (symbolic links, which are refused rather than followed, unreadable directories, " +
					"or sessions beyond the listing cap) are counted as Skipped in the header.",
			},
			{
				Title: "Agents",
				Body: "Opening a session lists its agents: the orchestrator first, then each sub-agent with its type, " +
					"as a tree, with the models used and the tokens in, out, and cached.\n" +
					"A ≥ before an Out count means a floor: that sub-agent's transcript was still being written, so the real figure is higher.\n" +
					"The orchestrator is the main conversation; its figures are never a floor.\n" +
					"When part of a transcript could not be read, the footer says the totals are approximate.",
			},
			{
				Title: "Agent columns",
				Body: "Agent: the orchestrator, or the sub-agent's type. ID: the start of the sub-agent's ID, long enough to tell two agents of the same type apart; " +
					"the orchestrator shows a dash. The filter matches the full ID.\n" +
					"Model, In, Out, Cache read, Cache write, Total: models used and token counts. " +
					"On a narrow terminal Cache write goes first, then Cache read, In, and Model. Agent, ID, Out, Total and Share stay.\n" +
					"Share: the agent's part of the session total, to one decimal, rounded down. " +
					"The orchestrator takes the rounding remainder, so the column adds up to 100%. A dash means the session has no tokens.\n" +
					"Press . to cycle: tree, then Total largest first, then Total smallest first, then the tree again. " +
					"Sorted, the list is flat: the branches go away. The sort stays when you open another session or press ctrl+r.",
			},
			{
				Title: "Live updates",
				Body: "While a session is open and still active, its figures are refreshed every 2 s and the header shows Updates: live.\n" +
					"Updates pause after 5 min without activity once every agent has finished (a session with an unfinished sub-agent stays live), or when its transcript is deleted: the header shows Updates: paused.\n" +
					"Press ctrl+r to resume. Re-read the whole session from the start with ctrl+r; coming back to the view only reads what changed since the last point read, and goes back to live if the session is being written to.\n" +
					"The list of sessions itself is not live: refresh it with ctrl+r at the sessions level.",
			},
			{
				Title: "Privacy",
				Body: "The sessions list reads the working directory and the file date alone. " +
					"Opening a session also reads its token counts, model names and agent types, and shows only the project's working directory, the date, the session ID, the agent types, the models and the tokens. " +
					"Prompts, replies, tool output and the paths of files a session touched are never displayed and never logged.",
			},
		},
	}
}

